  assert.equal(packed.length,p.gzipBytes);assert.equal(hash(packed),p.gzipSha256);
  const decoded=z.gunzipSync(packed);assert.equal(decoded.length,p.decodedBytes);const packet=JSON.parse(decoded);
  files={};const manifest=new Map(envelope.artifactManifest.map(x=>[x.path,x]));
  assert.deepEqual(Object.keys(packet.files).sort(),[...manifest.keys()].sort());
  for(const [path,entry]of Object.entries(packet.files)){const b=Buffer.from(entry.content,'base64');assert.equal(b.toString('base64'),entry.content);assert.equal(b.length,entry.bytes);assert.equal(hash(b),entry.sha256);assert.equal(b.length,manifest.get(path).bytes);assert.equal(hash(b),manifest.get(path).sha256);files[path]=b;}
  assert.equal(Object.keys(files).length,43);assert.equal(envelope.candidatePins.length,18);
  for(const pin of envelope.candidatePins){const b=files[pin.path];assert.equal(b.length,pin.bytes);assert.equal(hash(b),pin.sha256);assert.equal(git(b),pin.gitBlob);}
  assert.equal(git(files['independent-browser.mjs']),envelope.receiverBlob);assert.equal(git(files['recipient-contract.json']),envelope.recipientContractBlob);
  const receipt=JSON.parse(files['output/receipt.json']),native=JSON.parse(files['native.json']);
  assert.deepEqual(receipt,packet.receipt);assert.deepEqual(native,packet.native);
  assert.equal(native.exitCode,0);assert.equal(native.timeout,false);assert.equal(receipt.status,'pass');assert.equal(receipt.groups.length,15);assert(receipt.groups.every(g=>g.status==='pass'));
  assert.equal(receipt.sourcePreserved,true);assert.equal(receipt.rawStreamsComplete,true);assert.deepEqual(receipt.cleanupErrors,[]);
  assert.equal(receipt.childLifecycle.exitCode,0);assert.equal(receipt.childLifecycle.signal,null);assert.equal(receipt.childLifecycle.closed,true);assert.equal(receipt.childLifecycle.earlyClose,false);assert.equal(receipt.childLifecycle.error,null);
  assert.deepEqual(files['courses/convex-hull.json'],files['output/downloads/actual-convex-hull.json']);assert.deepEqual(files['courses/convex-hull.md'],files['output/downloads/actual-convex-hull.md']);
  answer({kind:'intake',timestamp:new Date().toISOString(),envelopeGit:git(bytes),envelopeSha256:hash(bytes),gzipSha256:hash(packed),decodedSha256:hash(decoded),decodedBytes:decoded.length,members:Object.keys(files).length,sourcePins:envelope.candidatePins.length,allMembersAndPinsExact:true,native,receiptKeys:Object.keys(receipt),groups:receipt.groups.map(g=>({name:g.name,status:g.status})),sourcePreserved:receipt.sourcePreserved,rawStreamsComplete:receipt.rawStreamsComplete,childLifecycle:receipt.childLifecycle,cleanupErrors:receipt.cleanupErrors,images:Object.keys(files).filter(p=>p.startsWith('output/screenshots/')).map(path=>({path,bytes:files[path].length,sha256:hash(files[path])})),archivedCodeExecuted:false,productReruns:0});return;
 }
 const request=JSON.parse(line);
 if(request.op==='get'){const b=files[request.path];assert(b);const value=request.encoding==='utf8'?b.toString('utf8'):b.toString('base64');answer({kind:'member',path:request.path,encoding:request.encoding,total:value.length,offset:request.offset??0,content:value.slice(request.offset??0,(request.offset??0)+(request.length??value.length))});}
 else if(request.op==='close'){answer({kind:'closed',timestamp:new Date().toISOString()});process.exit(0);}
 else throw new Error('Unknown request');
}
process.stdin.on('data',chunk=>{buffer+=chunk;for(;;){const i=buffer.indexOf('\n');if(i<0)break;const line=buffer.slice(0,i);buffer=buffer.slice(i+1);try{handle(line);}catch(error){answer({kind:'error',name:error.name,message:error.message,stack:error.stack});process.exitCode=1;process.stdin.destroy();break;}}});
answer({kind:'ready'});

